// Todo types (using Entity as base)
export type Todo = Entity & {
  children?: Todo[];
  parent_pk?: string;
  metadata?: {
    completed?: boolean;
    priority?: string;
    [key: string]: any;
  };
};

export type CreateTodoData = {
  title?: string;
  priority?: string;
  completed?: boolean;
  id?: string;
  pk_namespace?: string;
  metadata?: Record<string, any>;
};

export type UpdateTodoData = {
  title?: string;
  completed?: boolean;
  metadata?: {
    [key: string]: any;
  };
  priority?: string;
};

export type CreateSubtaskData = CreateTodoData;

